const input = $input.first();
const binary = input.binary || {};
const rawTestLimit =
  input.json?.testLimit ??
  input.json?.['Лимит строк из каждого файла для теста (0 = все)'] ??
  0;
const parsedTestLimit = Number(rawTestLimit);
const testLimitPerFile = Number.isFinite(parsedTestLimit)
  ? Math.max(0, Math.floor(parsedTestLimit))
  : 0;
const preferredKeys = ['file223', 'fileGos', 'fileKom'];
const binaryKeys = [
  ...preferredKeys.filter((key) => binary[key]),
  ...Object.keys(binary).filter((key) => !preferredKeys.includes(key)),
];

if (!binaryKeys.length) {
  throw new Error(
    'CSV-файлы не найдены в binary-данных Form Trigger. ' +
    'Загрузите хотя бы один CSV: 223, gos или kom.'
  );
}

function decodeCsv(source) {
  try {
    return new TextDecoder('utf-8', { fatal: true }).decode(source);
  } catch {}

  try {
    return new TextDecoder('windows-1251').decode(source);
  } catch (error) {
    throw new Error(
      'Не удалось прочитать CSV как UTF-8 или Windows-1251: ' +
      error.message
    );
  }
}

function detectDelimiter(text) {
  const firstLines = String(text || '')
    .replace(/^\uFEFF/, '')
    .split(/\r?\n/)
    .filter((line) => line.trim() !== '')
    .slice(0, 5);

  const candidates = [';', '\t', ','];
  let best = ';';
  let bestScore = -1;

  for (const delimiter of candidates) {
    const score = firstLines.reduce(
      (sum, line) => sum + line.split(delimiter).length - 1,
      0
    );

    if (score > bestScore) {
      best = delimiter;
      bestScore = score;
    }
  }

  return best;
}

function parseCsv(text, delimiter) {
  const source = String(text || '').replace(/^\uFEFF/, '');
  const table = [];
  let row = [];
  let value = '';
  let quoted = false;

  for (let i = 0; i < source.length; i++) {
    const char = source[i];

    if (quoted) {
      if (char === '"') {
        if (source[i + 1] === '"') {
          value += '"';
          i++;
        } else {
          quoted = false;
        }
      } else {
        value += char;
      }
      continue;
    }

    if (char === '"') {
      quoted = true;
      continue;
    }

    if (char === delimiter) {
      row.push(value);
      value = '';
      continue;
    }

    if (char === '\r' || char === '\n') {
      if (char === '\r' && source[i + 1] === '\n') i++;
      row.push(value);
      table.push(row);
      row = [];
      value = '';
      continue;
    }

    value += char;
  }

  if (value !== '' || row.length) {
    row.push(value);
    table.push(row);
  }

  return table;
}

function clean(value) {
  return String(value ?? '')
    .replace(/^\uFEFF/, '')
    .trim();
}

function makeColumnDefinitions(rawHeaders) {
  const used = new Map();
  let blankNumber = 0;

  return rawHeaders.map((rawHeader, index) => {
    const header = clean(rawHeader);
    let key;

    if (!header) {
      blankNumber++;
      // В текущих файлах пустая вторая колонка исторически называлась "0".
      key = blankNumber === 1 ? '0' : `__blank_${index + 1}`;
    } else {
      const count = used.get(header) || 0;
      used.set(header, count + 1);
      key = count === 0 ? header : `${header}_${count + 1}`;
    }

    return {
      index,
      header,
      key,
    };
  });
}

function reportIdFromFile(fileName, columnDefinitions, dataRows) {
  const lowerName = String(fileName || '')
    .toLowerCase()
    .replace(/ё/g, 'е');

  if (/(^|[_\-\s])223([_\-\s.]|$)/.test(lowerName)) return 1;
  if (/(^|[_\-\s])(gos|гос)([_\-\s.]|$)/.test(lowerName)) return 2;
  if (/(^|[_\-\s])(kom|ком)([_\-\s.]|$)/.test(lowerName)) return 3;

  const keys = new Set(columnDefinitions.map((column) => column.key));

  if (keys.has('Электронная площадка') && keys.has('Организатор')) {
    return 1;
  }

  if (keys.has('Размер обеспечения контракта') && keys.has('Торговая площадка')) {
    return 2;
  }

  if (keys.has('Источник') && keys.has('Название заказчика')) {
    return 3;
  }

  const lawIndex = columnDefinitions.find(
    (column) => column.key === 'Код ФЗ'
  )?.index;

  if (lawIndex !== undefined) {
    for (const values of dataRows.slice(0, 10)) {
      const law = clean(values[lawIndex]).toLowerCase();

      if (law.includes('223')) return 1;
      if (law === '44' || law.includes('44') || law.includes('94')) return 2;
      if (law.includes('commercial') || law.includes('ком')) return 3;
    }
  }

  return null;
}

function purchaseTypeFromReportId(reportId) {
  if (reportId === 1) return '223-ФЗ';
  if (reportId === 2) return '44/94-ФЗ';
  if (reportId === 3) return 'Коммерческие закупки';
  return null;
}

function expectedLabel(reportId) {
  if (reportId === 1) return '223';
  if (reportId === 2) return 'gos';
  if (reportId === 3) return 'kom';
  return 'unknown';
}

const allTenders = [];
const fileSummaries = [];
const seenReportIds = new Map();

for (const binaryKey of binaryKeys) {
  const fileInfo = binary[binaryKey] || {};
  const fileName = String(
    fileInfo.fileName ||
    fileInfo.file_name ||
    `${binaryKey}.csv`
  );

  const extension = fileName.split('.').pop().toLowerCase();

  if (extension !== 'csv') {
    throw new Error(`Ожидался CSV-файл, получен: ${fileName}`);
  }

  const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
  const text = decodeCsv(buffer);
  const delimiter = detectDelimiter(text);
  const matrix = parseCsv(text, delimiter);

  if (matrix.length < 2) {
    throw new Error(`CSV ${fileName} не содержит строк данных.`);
  }

  const rawHeaders = matrix[0];
  const columnDefinitions = makeColumnDefinitions(rawHeaders);
  const dataRows = matrix
    .slice(1)
    .filter((values) => values.some((value) => clean(value) !== ''));

  const selectedDataRows = testLimitPerFile > 0
    ? dataRows.slice(0, testLimitPerFile)
    : dataRows;

  const reportId = reportIdFromFile(
    fileName,
    columnDefinitions,
    dataRows
  );

  if (![1, 2, 3].includes(reportId)) {
    throw new Error(
      `Не удалось определить тип файла ${fileName}. ` +
      'Ожидается 223, gos или kom.'
    );
  }

  if (seenReportIds.has(reportId)) {
    throw new Error(
      `Загружено два файла типа ${expectedLabel(reportId)}: ` +
      `${seenReportIds.get(reportId)} и ${fileName}.`
    );
  }

  seenReportIds.set(reportId, fileName);

  for (let rowIndex = 0; rowIndex < selectedDataRows.length; rowIndex++) {
    const values = selectedDataRows[rowIndex];
    const row = {};
    const reportFields = {};

    for (const column of columnDefinitions) {
      const value = clean(values[column.index]);
      row[column.key] = value;
      reportFields[column.key] = value;
    }

    // Совместимость трёх схем Seldon с tender_autofill.
    if (!row['Организатор'] && row['Название заказчика']) {
      row['Организатор'] = row['Название заказчика'];
    }

    if (!row['Электронная площадка'] && row['Торговая площадка']) {
      row['Электронная площадка'] = row['Торговая площадка'];
    }

    if (
      !row['ИНН заказчика/организатора'] &&
      row['ИНН заказчика']
    ) {
      row['ИНН заказчика/организатора'] = row['ИНН заказчика'];
    }

    const id = clean(
      row.ID ??
      row.SeldonID ??
      row.SeldonId
    );

    row.reportId = reportId;
    row.purchaseType = purchaseTypeFromReportId(reportId);
    row.seldonId = id || null;
    row.lawCode = clean(row['Код ФЗ']) || null;
    row.toCode = clean(row['Код ТО']) || null;
    row.reportFields = reportFields;

    row.sourceFile = `form-upload://${fileName}`;
    row.sourceFileName = fileName;
    row.sourceBinaryKey = binaryKey;
    row.sourceRowNumber = rowIndex + 2;
    row.sourceColumnCount = columnDefinitions.length;
    row.sourceColumnDefinitions = columnDefinitions;

    allTenders.push(row);
  }

  fileSummaries.push({
    binaryKey,
    fileName,
    reportId,
    reportName: expectedLabel(reportId),
    sourceRowCount: dataRows.length,
    rowCount: selectedDataRows.length,
    testLimitApplied: testLimitPerFile > 0,
    columnCount: columnDefinitions.length,
    delimiter,
    headers: columnDefinitions.map((column) => ({
      header: column.header,
      key: column.key,
      index: column.index,
    })),
  });
}

if (!allTenders.length) {
  throw new Error('В загруженных CSV-файлах не найдено ни одного тендера.');
}

const datesFromNames = fileSummaries
  .map((file) => file.fileName.match(/\d{4}-\d{2}-\d{2}/)?.[0])
  .filter(Boolean);

const uniqueDates = [...new Set(datesFromNames)];

const batchDate =
  uniqueDates.length === 1
    ? uniqueDates[0]
    : new Intl.DateTimeFormat('en-CA', {
        timeZone: 'Europe/Moscow',
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
      }).format(new Date());

const generatedAt = new Date().toISOString();
const batchId =
  `form-${batchDate}-${generatedAt.replace(/[-:.TZ]/g, '').slice(0, 14)}`;

return [{
  json: {
    batchId,
    batchDate,
    generatedAt,
    count: allTenders.length,
    fileCount: fileSummaries.length,
    loadedReportIds: [...seenReportIds.keys()].sort((a, b) => a - b),
    testLimitPerFile,
    files: fileSummaries,
    tenders: allTenders,
    sourceFile: `form-upload://${fileSummaries.map((file) => file.reportName).join('+')}`,
  },
}];

function firstPresent(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null) return value;
  }
  return undefined;
}

function pickNonEmpty(obj, keys) {
  for (const key of keys) {
    const value = obj?.[key];

    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ''
    ) {
      return value;
    }
  }

  return null;
}

function emptyToNull(value) {
  if (value === undefined || value === null) return null;
  const text = String(value).trim();

  if (
    !text ||
    ['null', '[null]', 'undefined', '[undefined]'].includes(text.toLowerCase())
  ) {
    return null;
  }

  return text;
}

function resolveReportId(row) {
  const explicit = Number(
    pickNonEmpty(row, ['reportId', 'report_id', 'ReportId'])
  );

  if ([1, 2, 3].includes(explicit)) return explicit;

  const type = String(
    pickNonEmpty(row, [
      'purchaseType',
      'purchase_type',
      'tenderType',
      'type',
      'Тип закупки',
      'ТипЗакупки',
    ]) || ''
  )
    .trim()
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[–—]/g, '-');

  if (['223-фз', '223 фз', '223', '1'].includes(type)) return 1;

  if (
    [
      '44/94-фз',
      '44/94 фз',
      '44-фз',
      '44 фз',
      '94-фз',
      '94 фз',
      '44',
      '94',
      '2',
      'гос',
    ].includes(type)
  ) {
    return 2;
  }

  if (
    [
      'коммерческие закупки',
      'коммерческая закупка',
      'коммерческие',
      'commercial',
      'kom',
      '3',
    ].includes(type)
  ) {
    return 3;
  }

  const law = String(
    pickNonEmpty(row, ['lawCode', 'Код ФЗ', 'federalLaw']) || ''
  ).toLowerCase();

  if (law.includes('223')) return 1;
  if (law === '44' || law.includes('44') || law.includes('94')) return 2;
  if (law.includes('commercial') || law.includes('ком')) return 3;

  return null;
}

const REPORT_COLUMNS = {
  1: [
    { header: 'ID', key: 'ID' },
    { header: '', key: '0' },
    { header: 'Осталось дней', key: 'Осталось дней' },
    { header: 'Статус закупки', key: 'Статус закупки' },
    { header: 'Электронная площадка', key: 'Электронная площадка' },
    { header: 'Способ закупки', key: 'Способ закупки' },
    { header: 'Наименование', key: 'Наименование' },
    { header: 'Организатор', key: 'Организатор' },
    { header: 'Начальная цена', key: 'Начальная цена' },
    { header: 'Конечная цена', key: 'Конечная цена' },
    { header: 'Валюта', key: 'Валюта' },
    { header: 'Дата начала приёма заявок', key: 'Дата начала приёма заявок' },
    { header: 'Дата окончания приёма заявок', key: 'Дата окончания приёма заявок' },
    { header: 'Дата изменения', key: 'Дата изменения' },
    { header: '№ извещения', key: '№ извещения' },
    { header: 'Ссылка на тендер', key: 'Ссылка на тендер' },
    { header: 'Регион заказчика/организатора', key: 'Регион заказчика/организатора' },
    { header: 'ИНН заказчика/организатора', key: 'ИНН заказчика/организатора' },
    { header: 'Дата проведения аукциона', key: 'Дата проведения аукциона' },
    { header: 'Размер обеспечения заявки', key: 'Размер обеспечения заявки' },
    { header: 'Код ТО', key: 'Код ТО' },
    { header: 'Код ФЗ', key: 'Код ФЗ' },
  ],
  2: [
    { header: 'ID', key: 'ID' },
    { header: 'Степень завершения', key: 'Степень завершения' },
    { header: 'Осталось дней', key: 'Осталось дней' },
    { header: 'Статус закупки', key: 'Статус закупки' },
    { header: '№ извещения', key: '№ извещения' },
    { header: 'Способ закупки', key: 'Способ закупки' },
    { header: 'Наименование', key: 'Наименование' },
    { header: 'Название заказчика', key: 'Название заказчика' },
    { header: 'Начальная цена', key: 'Начальная цена' },
    { header: 'Конечная цена', key: 'Конечная цена' },
    { header: 'Валюта', key: 'Валюта' },
    { header: 'Дата начала приёма заявок', key: 'Дата начала приёма заявок' },
    { header: 'Дата окончания приёма заявок', key: 'Дата окончания приёма заявок' },
    { header: 'Дата изменения', key: 'Дата изменения' },
    { header: 'Ссылка на тендер', key: 'Ссылка на тендер' },
    { header: 'Регион заказчика/организатора', key: 'Регион заказчика/организатора' },
    { header: 'ИНН заказчика', key: 'ИНН заказчика' },
    { header: 'Размер обеспечения заявки', key: 'Размер обеспечения заявки' },
    { header: 'Дата проведения аукциона', key: 'Дата проведения аукциона' },
    { header: 'Размер обеспечения контракта', key: 'Размер обеспечения контракта' },
    { header: 'Торговая площадка', key: 'Торговая площадка' },
    { header: 'Код ТО', key: 'Код ТО' },
    { header: 'Код ФЗ', key: 'Код ФЗ' },
  ],
  3: [
    { header: 'ID', key: 'ID' },
    { header: '', key: '0' },
    { header: 'Степень завершения', key: 'Степень завершения' },
    { header: 'Осталось дней', key: 'Осталось дней' },
    { header: 'Статус закупки', key: 'Статус закупки' },
    { header: 'Способ закупки', key: 'Способ закупки' },
    { header: 'Источник', key: 'Источник' },
    { header: 'Наименование', key: 'Наименование' },
    { header: 'Название заказчика', key: 'Название заказчика' },
    { header: 'Начальная цена', key: 'Начальная цена' },
    { header: 'Валюта', key: 'Валюта' },
    { header: 'Дата начала приёма заявок', key: 'Дата начала приёма заявок' },
    { header: 'Дата окончания приёма заявок', key: 'Дата окончания приёма заявок' },
    { header: 'Дата изменения', key: 'Дата изменения' },
    { header: 'Ссылка на тендер', key: 'Ссылка на тендер' },
    { header: 'Регион заказчика/организатора', key: 'Регион заказчика/организатора' },
    { header: 'ИНН заказчика', key: 'ИНН заказчика' },
    { header: 'Код ТО', key: 'Код ТО' },
    { header: 'Код ФЗ', key: 'Код ФЗ' },
  ],
};

function buildReportFields(row, reportId) {
  const supplied =
    row?.reportFields &&
    typeof row.reportFields === 'object' &&
    !Array.isArray(row.reportFields)
      ? row.reportFields
      : {};

  const result = { ...supplied };

  for (const column of REPORT_COLUMNS[reportId] || []) {
    result[column.key] = firstPresent(
      supplied[column.key],
      column.header ? supplied[column.header] : undefined,
      row?.[column.key],
      column.header ? row?.[column.header] : undefined,
      ''
    );
  }

  if (!result.ID) {
    result.ID = firstPresent(
      row?.ID,
      row?.SeldonID,
      row?.SeldonId,
      row?.seldonId,
      ''
    );
  }

  if (!result['Код ТО']) {
    result['Код ТО'] = firstPresent(row?.toCode, '');
  }

  if (!result['Код ФЗ']) {
    result['Код ФЗ'] = firstPresent(
      row?.lawCode,
      reportId === 1 ? '223' : reportId === 2 ? '44' : 'Commercial'
    );
  }

  return result;
}

const rows = [];

for (const item of $input.all()) {
  const payload = item.json || {};

  if (Array.isArray(payload.tenders)) {
    for (const tender of payload.tenders) {
      rows.push({
        row: tender || {},
        batchId: payload.batchId || null,
        batchDate: payload.batchDate || null,
        generatedAt: payload.generatedAt || null,
        sourceFile: payload.sourceFile || tender?.sourceFile || null,
      });
    }
  } else {
    rows.push({
      row: payload,
      batchId: payload.batchId || null,
      batchDate: payload.batchDate || null,
      generatedAt: payload.generatedAt || null,
      sourceFile: payload.sourceFile || null,
    });
  }
}

return rows.map((entry, index) => {
  const row = entry.row;
  const reportId = resolveReportId(row);

  const purchaseType =
    pickNonEmpty(row, [
      'purchaseType',
      'purchase_type',
      'tenderType',
      'type',
      'Тип закупки',
      'ТипЗакупки',
    ]) ||
    (reportId === 1
      ? '223-ФЗ'
      : reportId === 2
        ? '44/94-ФЗ'
        : reportId === 3
          ? 'Коммерческие закупки'
          : null);

  const seldonId = emptyToNull(
    pickNonEmpty(row, [
      'seldonId',
      'seldon_id',
      'SeldonId',
      'SeldonID',
      'Seldon ID',
      'ID',
    ])
  );

  const noticeOrEtpId = emptyToNull(
    pickNonEmpty(row, [
      'etpId',
      'etp_id',
      'EtpId',
      'Номер извещения',
      '№ извещения',
      'purchaseNumber',
      'notificationNumber',
    ])
  );

  const etpId = seldonId ? null : noticeOrEtpId;
  const toCode = emptyToNull(
    pickNonEmpty(row, ['toCode', 'Код ТО'])
  );

  const lawCode =
    emptyToNull(pickNonEmpty(row, ['lawCode', 'Код ФЗ'])) ||
    (reportId === 1 ? '223' : reportId === 2 ? '44' : reportId === 3 ? 'Commercial' : null);

  const reportFields = buildReportFields(row, reportId);
  const errors = [];

  if (!reportId) {
    errors.push('не определён reportId/purchaseType');
  }

  if ((seldonId ? 1 : 0) + (etpId ? 1 : 0) !== 1) {
    errors.push('должен быть заполнен ровно один из seldonId/etpId');
  }

  const rowNumber = index + 1;
  const batchResultKey = reportId
    ? `daily:${entry.batchId || 'direct'}:${reportId}:${seldonId || ('etp:' + etpId)}`
    : `daily:${entry.batchId || 'direct'}:invalid:${rowNumber}`;

  return {
    json: {
      ...row,
      batchId: entry.batchId,
      batchDate: entry.batchDate,
      batchGeneratedAt: entry.generatedAt,
      rowNumber,
      purchaseType: purchaseType ? String(purchaseType).trim() : null,
      sectionName:
        String(row.sectionName || row['Раздел ТО'] || '').trim() || null,
      filterName:
        String(row.filterName || row['Исходное имя фильтра'] || '').trim() || null,
      reportId,
      seldonId,
      etpId,
      toCode,
      lawCode,
      reportFields,
      seldonPurchase:
        row.seldonPurchase ||
        row.purchase ||
        row.rawPurchase ||
        null,
      batchMode: true,

      // tender_autofill пока ожидает batchCacheKey для возврата результата.
      // Это только идентификатор строки запуска; Data Table в этом workflow больше нет.
      batchCacheKey: batchResultKey,
      batchResultKey,

      sourceFile:
        entry.sourceFile ||
        row.sourceFile ||
        `form-upload://${row.sourceFileName || 'unknown.csv'}`,
      inputValid: errors.length === 0,
      inputError: errors.join('; '),
    },
  };
});

const rows = $input
  .all()
  .map(item => item.json || {})
  .filter(row => row && typeof row === 'object');

if (!rows.length) {
  throw new Error('После нормализации не найдено ни одного тендера.');
}

function firstDefined(...values) {
  for (const value of values) {
    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ''
    ) {
      return value;
    }
  }

  return null;
}

function reportName(reportId) {
  if (Number(reportId) === 1) return '223';
  if (Number(reportId) === 2) return 'gos';
  if (Number(reportId) === 3) return 'kom';
  return 'unknown';
}

let packageInput = {};

try {
  packageInput =
    $('Прочитать CSV из формы и собрать пакет').first().json || {};
} catch {}

const first = rows[0];

const batchId =
  firstDefined(
    first.batchId,
    packageInput.batchId
  ) ||
  `daily-${new Date().toISOString().replace(/[-:.TZ]/g, '').slice(0, 14)}`;

const batchDate =
  firstDefined(
    first.batchDate,
    packageInput.batchDate
  ) ||
  new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Europe/Moscow',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(new Date());

const sourceFiles =
  Array.isArray(packageInput.files)
    ? packageInput.files
    : [];

const jobs = rows.map((row, index) => {
  const reportId =
    Number(row.reportId) || null;

  const seldonId =
    firstDefined(
      row.seldonId,
      row.ID,
      row.SeldonID
    );

  const etpId =
    seldonId
      ? null
      : firstDefined(
          row.etpId,
          row['№ извещения']
        );

  const rowNumber =
    Number(row.rowNumber) ||
    index + 1;

  const recordKey = String(
    firstDefined(
      row.batchResultKey,
      row.batchCacheKey,
      reportId && seldonId
        ? `daily:${batchId}:${reportId}:${seldonId}`
        : reportId && etpId
          ? `daily:${batchId}:${reportId}:etp:${etpId}`
          : `daily:${batchId}:invalid:${rowNumber}`
    )
  );

  const inputValid =
    row.inputValid === true;

  const inputError =
    String(row.inputError || '').trim();

  const payload = {
    ...row,

    batchId,
    batchDate,
    rowNumber,

    jobRecordKey:
      recordKey,

    asyncDispatch:
      true,

    batchMode:
      true,

    batchCacheKey:
      recordKey,

    batchResultKey:
      recordKey
  };

  return {
    record_key:
      recordKey,

    report_id:
      reportId,

    report_name:
      reportName(reportId),

    seldon_id:
      seldonId === null
        ? null
        : String(seldonId),

    etp_id:
      etpId === null
        ? null
        : String(etpId),

    row_number:
      rowNumber,

    input_valid:
      inputValid,

    input_error:
      inputError,

    payload,

    report_fields:
      row.reportFields &&
      typeof row.reportFields === 'object' &&
      !Array.isArray(row.reportFields)
        ? row.reportFields
        : {}
  };
});

const validCount =
  jobs.filter(job => job.input_valid).length;

const invalidCount =
  jobs.length - validCount;

return [
  {
    json: {
      batchId,
      batchDate,

      expectedCount:
        jobs.length,

      validCount,
      invalidCount,

      sourceFiles,
      jobs,

      createdAt:
        new Date().toISOString()
    }
  }
];

const stored = $input.first().json || {};

const expectedCount =
  Number(stored.expectedCount || 0);

const queuedCount =
  Number(stored.validCount || 0);

const invalidCount =
  Number(stored.invalidCount || 0);

return [
  {
    json: {
      status:
        'queued',

      batchId:
        stored.batchId || null,

      batchDate:
        stored.batchDate || null,

      expectedCount,
      queuedCount,
      invalidCount,

      storedJobCount:
        Number(stored.storedJobCount || 0),

      maxTenderActive:
        5,

      message:
        'Batch сохранён в PostgreSQL. ' +
        'Tender Worker здесь не запускаются.',

      nextStep:
        'Controller/Finalizer будет запускать не более 10 ' +
        'Tender Worker одновременно.'
    }
  }
];
